import base64
import zlib
import pygame

FW, FH = 41, 59
FPAL = ""
FDATA = ""
FCACHE = {}


def folk_frame(var, fr):
  """Side-view running townsfolk facing left: 0 blacksmith, 1 villager, 2 merchant, 3 knight; 4 frames each."""
  if "raw" not in FCACHE:
    FCACHE["pal"] = [None] + [tuple(int(FPAL[i + k:i + k + 2], 16) for k in (0, 2, 4)) for i in range(0, len(FPAL), 6)]
    FCACHE["raw"] = zlib.decompress(base64.b64decode(FDATA))
  key = (var % 4, fr % 4)
  if key not in FCACHE:
    raw, pal = FCACHE["raw"], FCACHE["pal"]
    s = pygame.Surface((FW, FH), pygame.SRCALPHA)
    base = (key[0] * 4 + key[1]) * FW * FH
    for i in range(FW * FH):
      v = raw[base + i]
      if v:
        s.set_at((i % FW, i // FW), pal[v] + (255,))
    FCACHE[key] = s
  return FCACHE[key]
